examples.template:
NavigationStack {
    VStack(spacing: 0) {
        Text("Chat with the support team.")
            .monarchTextStyle(.body)
            .foregroundStyle(theme.colors.textMuted)
            .frame(maxWidth: .infinity, alignment: .leading)
            .padding(.horizontal, theme.spacing.space4)
        Picker("Section", selection: $showsChat) {
            Text("Chat").tag(true)
            Text("Help").tag(false)
        }
        .pickerStyle(.segmented)
        .padding(theme.spacing.space4)
        if showsChat {
            Text({{chat.expectedReply}})
                .monarchTextStyle(.caption)
                .foregroundStyle(theme.colors.textMuted)
                .frame(maxWidth: .infinity, alignment: .leading)
                .padding(.horizontal, theme.spacing.space4)
            ScrollView {
                LazyVStack(alignment: .leading, spacing: theme.spacing.space3) {
                    VStack(spacing: theme.spacing.space3) {
                        Text("09:58 UTC")
                        Text({{chat.system}})
                    }
                    .monarchTextStyle(.caption)
                    .foregroundStyle(theme.colors.textMuted)
                    .frame(maxWidth: .infinity)
                    ForEach(messages, id: \.self) { text in
                        MonarchMessageRow(MonarchMessageRowAuthor({{chat.agent}}), time: now, now: now, timeStyle: .clock) {
                            Text(text)
                        }
                    }
                }
                .padding(.horizontal, theme.spacing.space4)
            }
            .safeAreaInset(edge: .bottom) {
                VStack(alignment: .leading, spacing: theme.spacing.space2) {
                    MonarchMessageComposer(
                        "Message support",
                        text: $draft,
                        placeholder: "Write a message…",
                        showsEmojiButton: false,
                        showsFormatting: false
                    ) { message in
                        messages.append(message.text)
                    }
                    HStack(spacing: theme.spacing.space4) {
                        MonarchStatusDot("System status: " + {{status}}, tone: .success)
                        if let help = URL(string: "https://help.example.com") {
                            Link(destination: help) { Label("Help Center", systemImage: "book") }
                                .monarchTextStyle(.caption)
                                .buttonStyle(.monarchLink(.standalone, isExternal: true))
                        }
                    }
                }
                .padding(theme.spacing.space4)
            }
        } else {
            List {
                Section("Popular articles") {
                    Button({{articles.0}}) {}
                    Button({{articles.1}}) {}
                    Button({{articles.2}}) {}
                }
                Section("Contact us") {
                    if let email = URL(string: "mailto:" + {{contact.description}}) {
                        Link(destination: email) {
                            VStack(alignment: .leading) {
                                Text({{contact.label}})
                                Text({{contact.description}}).monarchTextStyle(.caption)
                            }
                        }
                    }
                }
                Section("Status") {
                    MonarchStatusDot({{status}}, tone: .success)
                    if let status = URL(string: "https://status.example.com") {
                        Link("System status", destination: status)
                            .buttonStyle(.monarchLink(.standalone, isExternal: true))
                    }
                }
            }
        }
    }
    .monarchCanvas()
    .navigationTitle({{trigger}})
    #if os(iOS)
    .navigationBarTitleDisplayMode(.inline)
    #endif
}
.frame(minHeight: theme.spacing.space24 * 5)

